const NGO_ABOUT_11_SEED = () => {
  const pack = getContentBundle().categories?.NGO?.sections?.About as
    | Record<string, Record<string, unknown>>
    | undefined;
  return pack?.["About-11"] && typeof pack["About-11"] === "object"
    ? pack["About-11"]
    : {};
};

const NGO_WHY_11_SEED = () => {
  const pack = getContentBundle().categories?.NGO?.sections?.WhyChooseUs as
    | Record<string, Record<string, unknown>>
    | undefined;
  if (pack?.["WhyChooseUs-11"] && typeof pack["WhyChooseUs-11"] === "object") {
    return pack["WhyChooseUs-11"];
  }
  const aboutPage = getContentBundle().categories?.NGO?.sections?.AboutPage as
    | Record<string, Record<string, unknown>>
    | undefined;
  const nested = aboutPage?.["AboutPage-11"]?.whyChooseUs;
  return nested && typeof nested === "object" && !Array.isArray(nested)
    ? (nested as Record<string, unknown>)
    : {};
};

const mergeNgoWhy11Seed = (base: Record<string, unknown> | undefined) => {
  const seed = NGO_WHY_11_SEED();
  const next = { ...(base ?? {}) } as Record<string, unknown>;
  const intro = isPlainRecord(next.introduction) ? next.introduction : null;
  if (
    !intro ||
    (isJunkAboutText(intro.badge) &&
      isJunkAboutText(
        isPlainRecord(intro.title) ? intro.title.normal : intro.title,
      ) &&
      isJunkAboutText(intro.description))
  ) {
    delete next.introduction;
  }
  if (!Array.isArray(next.features) || next.features.length === 0) {
    delete next.features;
  }
  const side = isPlainRecord(next.sideImage) ? next.sideImage : null;
  if (!side || typeof side.src !== "string" || !side.src.trim()) {
    delete next.sideImage;
  }
  if (!isPlainRecord(next.overlayCard)) delete next.overlayCard;
  return { ...seed, ...next };
};

const NGO_HELP_11_SEED = () => {
  const pack = getContentBundle().categories?.NGO?.sections?.Help as
    | Record<string, Record<string, unknown>>
    | undefined;
  if (pack?.["Help-11"] && typeof pack["Help-11"] === "object") {
    return pack["Help-11"];
  }
  const aboutPage = getContentBundle().categories?.NGO?.sections?.AboutPage as
    | Record<string, Record<string, unknown>>
    | undefined;
  const nested = aboutPage?.["AboutPage-11"]?.howWeHelp;
  return nested && typeof nested === "object" && !Array.isArray(nested)
    ? (nested as Record<string, unknown>)
    : {};
};

const mergeNgoHelp11Seed = (base: Record<string, unknown> | undefined) => {
  const seed = NGO_HELP_11_SEED();
  const next = { ...(base ?? {}) } as Record<string, unknown>;
  if (isJunkAboutText(next.badge)) delete next.badge;
  if (isJunkAboutText(next.title)) delete next.title;
  if (isJunkAboutText(next.description)) delete next.description;
  if (isJunkAboutText(next.icon)) delete next.icon;
  if (!Array.isArray(next.cards) || next.cards.length === 0) {
    delete next.cards;
  }
  return { ...seed, ...next };
};

const isJunkAboutText = (value: unknown) => {
  if (typeof value !== "string") return true;
  const text = value.trim();
  if (!text) return true;
  return /^(c+|test|asdf|xxx+|n+\/a+)$/i.test(text);
};
