const limitLinkText = (value: string) => value.slice(0, MAX_LINK_TEXT_LENGTH);

const clampBannerHeight = (height: number) => {
  if (!Number.isFinite(height)) return 70;

  return Math.min(100, Math.max(40, height));
};

const ngo11SlideFromItem = (item: Record<string, unknown>): BannerSlideData => {
  const image =
    (typeof item.bgImageUrl === "string" && item.bgImageUrl) ||
    (typeof item.image === "string" && item.image) ||
    "";
  const video =
    (typeof item.videoUrl === "string" && item.videoUrl) ||
    (typeof item.video === "string" && item.video) ||
    "";
  const buttons = Array.isArray(item.buttons)
    ? (item.buttons as ButtonData[])
    : undefined;
  return {
    image,
    video: video || undefined,
    alt: typeof item.alt === "string" ? item.alt : "",
    pretitle: typeof item.pretitle === "string" ? item.pretitle : undefined,
    title: typeof item.title === "string" ? item.title : "",
    desc: typeof item.desc === "string" ? item.desc : undefined,
    buttons,
    button: buttons?.[0],
    secondButton: buttons?.[1],
  };
};

const ngo11ItemFromSlide = (slide: BannerSlideData) => ({
  ...slide,
  bgImageUrl: slide.image,
  videoUrl: slide.video,
  buttons:
    Array.isArray(slide.buttons) && slide.buttons.length
      ? slide.buttons
      : [slide.button, slide.secondButton].filter(Boolean),
});

const normalizeNgoTheme2BannerData = (
  variant: string,
  data:
    | (Record<string, unknown> & {
        bannerSlides?: BannerSlideData[];
        items?: unknown[];
      })
    | undefined,
) => {
  if (variant !== "Banner-11" || !data) return data;
  const fromSlides = Array.isArray(data.bannerSlides) ? data.bannerSlides : [];
  const fromItems = Array.isArray(data.items)
    ? data.items.filter(
        (item): item is Record<string, unknown> =>
          Boolean(item) && typeof item === "object" && !Array.isArray(item),
      )
    : [];
  const bannerSlides = fromSlides.length
    ? fromSlides.map((slide) => ({
        ...slide,
        image: slide.image || (slide as { bgImageUrl?: string }).bgImageUrl || "",
      }))
    : fromItems.map(ngo11SlideFromItem);
  return { ...data, bannerSlides };
};

const getDefaultBannerData = (
  variant: string,
  sourceData: SectionData = {},
): SectionData | undefined => {
  const sourceImage = sourceData.backgroundImage ?? "/bg1.jpg";
  const sourceVideo = sourceData.backgroundVideo ?? "/video.mp4";
  const sourceSlides = Array.isArray(sourceData.bannerSlides)
    ? sourceData.bannerSlides
    : [];

  if (variant === "Banner-4") {
    return {
      ...sourceData,
      bannerHeight: 70,
      bannerSlides: sourceSlides.length
        ? sourceSlides.map((slide) => ({
            ...slide,
            image: slide.image || sourceImage,
            video: slide.video || sourceVideo,
          }))
        : [
            {
              image: sourceImage,
              video: sourceVideo,
              alt: sourceData.backgroundImageTitle ?? "Category video slide",
              title: sourceData.title ?? "Category video banner",
              desc:
                sourceData.desc ??
                "Use category-specific motion behind every banner slide.",
              button: {
                label: "Explore",
                href: "#",
                variant: "primary",
              },
            },
          ],
    };
  }

  if (variant !== "Banner-3") return undefined;

  return {
    ...sourceData,
    bannerHeight: 70,
    bannerSlides: sourceSlides.length
      ? sourceSlides.map((slide) => ({
          ...slide,
          image: slide.image || sourceImage,
        }))
      : [
          {
            image: sourceImage,
            alt: sourceData.backgroundImageTitle ?? "Category slide",
            title: sourceData.title ?? "Category image slider",
            desc:
              sourceData.desc ??
              "Use category-specific images across every slider layout.",
            button: {
              label: "Explore",
              href: "#",
              variant: "primary",
            },
          },
        ],
  };
};

