class FieldErrorBoundary extends Component<
  { children: ReactNode; popup?: boolean },
  { message: string }
> {
  state = { message: "" };

  static getDerivedStateFromError(error: Error) {
    return { message: error?.message || "This field could not be shown." };
  }

  render() {
    if (this.state.message) {
      if (this.props.popup) {
        return (
          <div className="pointer-events-auto fixed inset-0 z-[10050] grid place-items-center bg-slate-950/40 p-4">
            <div className="w-[min(92vw,420px)] rounded-2xl border border-red-200 bg-white p-5 shadow-xl">
              <p className="text-sm font-semibold text-slate-900">
                This section popup hit an error
              </p>
              <p className="mt-2 text-xs text-red-700">{this.state.message}</p>
            </div>
          </div>
        );
      }
      return (
        <p className="rounded-lg border border-red-200 bg-red-50 px-2.5 py-2 text-xs text-red-700">
          {this.state.message}
        </p>
      );
    }
    return this.props.children;
  }
}

const readAnchoredMenuBox = (anchor: HTMLElement | null, menuHeight: number) => {
  if (!anchor) return null;
  const rect = anchor.getBoundingClientRect();
  const gap = 4;
  const height = Math.min(menuHeight, 224);
  const spaceBelow = window.innerHeight - rect.bottom - gap;
  const top =
    spaceBelow < 120 && rect.top > spaceBelow
      ? Math.max(8, rect.top - height - gap)
      : rect.bottom + gap;
  return { top, left: rect.left, width: rect.width };
};

const EditorAnchoredMenu = ({
  open,
  anchorRef,
  onClose,
  scrollable = false,
  children,
}: {
  open: boolean;
  anchorRef: RefObject<HTMLDivElement | null>;
  onClose: () => void;
  scrollable?: boolean;
  children: ReactNode;
}) => {
  const menuRef = useRef<HTMLDivElement>(null);
  const onCloseRef = useRef(onClose);
  onCloseRef.current = onClose;
  const [box, setBox] = useState<{ top: number; left: number; width: number } | null>(null);

  useLayoutEffect(() => {
    if (!open) return;
    const place = () => {
      const next = readAnchoredMenuBox(
        anchorRef.current,
        menuRef.current?.offsetHeight || 224,
      );
      setBox((current) => {
        if (
          current &&
          next &&
          current.top === next.top &&
          current.left === next.left &&
          current.width === next.width
        ) {
          return current;
        }
        return next;
      });
    };
    place();
    const onPointerDown = (event: MouseEvent) => {
      const target = event.target as Node;
      if (anchorRef.current?.contains(target) || menuRef.current?.contains(target)) return;
      onCloseRef.current();
    };
    window.addEventListener("resize", place);
    window.addEventListener("scroll", place, true);
    document.addEventListener("mousedown", onPointerDown);
    return () => {
      window.removeEventListener("resize", place);
      window.removeEventListener("scroll", place, true);
      document.removeEventListener("mousedown", onPointerDown);
    };
  }, [open, anchorRef]);

  if (!open || typeof document === "undefined") return null;
  return createPortal(
    <div
      ref={menuRef}
      style={{
        position: "fixed",
        top: box?.top ?? -9999,
        left: box?.left ?? 0,
        width: box?.width ?? 0,
        zIndex: 10060,
      }}
      className={`rounded-lg border border-slate-200 bg-white py-1 shadow-[0_8px_24px_rgba(15,23,42,0.12)] ${
        scrollable ? "max-h-56 overflow-auto" : ""
      }`}
    >
      {children}
    </div>,
    document.body,
  );
};

