const isButtonIconFieldName = (fieldName: string) =>
  /^buttonIcon$/i.test(fieldName.trim());
const isButtonIconPositionFieldName = (fieldName: string) =>
  /^iconPosition$/i.test(fieldName.trim());
const isFeatureIconPath = (path: GenericFieldPath) =>
  path.length >= 2 && path[0] === "features" && path[path.length - 1] === "icon";
const isWhyChooseUsIconPath = (path: GenericFieldPath) =>
  path.length >= 2 &&
  path[0] === "whyChooseUsItems" &&
  path[path.length - 1] === "icon";
const isProcessIconPath = (path: GenericFieldPath) =>
  path.length >= 2 &&
  path[0] === "steps" &&
  path[path.length - 1] === "icon" &&
  // Service WhyChooseUs steps use mainIcon/subIcon (website icons), not Process icons.
  !/^(mainIcon|subIcon)$/i.test(String(path[path.length - 1]));
const isMissionValueIconPath = (path: GenericFieldPath) =>
  path.length >= 2 && path[0] === "values" && path[path.length - 1] === "icon";
const isWebsiteIconNamedField = (fieldName: string) =>
  /^(mainIcon|subIcon|iconName)$/i.test(fieldName.trim());

const formatServiceCleaningLayoutName = (variant: string) => {
  if (/WhyChooseUs/i.test(variant)) return "Service Work Process";
  if (/Banner/i.test(variant)) return "Service Banner";
  if (/Header/i.test(variant)) return "Service Header";
  if (/Footer/i.test(variant)) return "Service Footer";
  if (/Stats/i.test(variant)) return "Service Stats";
  return variant
    .replace(/^(Service|Cleaning)/, "Service ")
    .replace(/([a-z])([A-Z])/g, "$1 $2")
    .replace(/(\d+)$/, " $1")
    .replace(/\s+/g, " ")
    .trim();
};

const sortObjectEntriesByPreferredOrder = (
  entries: Array<[string, unknown]>,
  preferredOrder: string[],
) => {
  entries.sort((left, right) => {
    const leftIndex = preferredOrder.indexOf(left[0]);
    const rightIndex = preferredOrder.indexOf(right[0]);
    const leftRank = leftIndex === -1 ? preferredOrder.length : leftIndex;
    const rightRank = rightIndex === -1 ? preferredOrder.length : rightIndex;
    return leftRank - rightRank;
  });
  return entries;
};

const contentFieldRank = (key: string) => {
  const normalized = key.toLowerCase();
  if (
    normalized.endsWith("imagealt") ||
    normalized.endsWith("imagetitle") ||
    (normalized.endsWith("alt") && normalized.includes("image"))
  ) {
    return 6;
  }
  if (
    normalized === "pretitle" ||
    normalized.endsWith("pretitle") ||
    normalized === "eyebrow" ||
    normalized.endsWith("eyebrow")
  ) {
    return 0;
  }
  if (normalized === "subtitle" || normalized.endsWith("subtitle")) return 2;
  if (normalized === "title" || normalized.endsWith("title")) return 1;
  if (
    normalized.includes("description") ||
    normalized === "desc" ||
    normalized.startsWith("desc") ||
    normalized.endsWith("desc") ||
    normalized === "detail" ||
    normalized.endsWith("detail")
  ) {
    return 3;
  }
  if (normalized.includes("quote")) return 4;
  if (
    normalized.includes("image") ||
    normalized.includes("photo") ||
    normalized.includes("poster") ||
    normalized.includes("thumbnail")
  ) {
    return 5;
  }
  return 100;
};

const sortContentFieldsFirst = (entries: Array<[string, unknown]>) =>
  [...entries].sort(
    (left, right) => contentFieldRank(left[0]) - contentFieldRank(right[0]),
  );

