const formatFieldLabel = (fieldName: string) => {
  const specialLabels: Record<string, string> = {
    title_line1: "Title line 1",
    title_line2: "Title line 2",
    title_highlight: "Title highlight",
    image_attribute: "Image attribute",
    alt: "Image attribute",
  };
  if (specialLabels[fieldName]) return specialLabels[fieldName];
  return fieldName
    .replace(/_/g, " ")
    .replace(/([A-Z])/g, " $1")
    .replace(/\s+/g, " ")
    .trim()
    .replace(/^./, (letter) => letter.toUpperCase());
};

